void cursor_on(uint8 row, uint8 line, uint8 onByte, uint8 offByte)
{

		cursor.row = row;
		cursor.line = line;
		cursor.on_byte = onByte;
		cursor.off_byte = offByte;
		cursor.status = CURSOR_ON;
	
}

void cursor_off(void)
{

		cursor.status = CURSOR_OFF;
}




