uint8 bl_timer = 0;
void start_back_light(uint8 timer)
{
	//if(isColorScreen == false)
	{
		if(timer == 0) BL_OFF();
		else BL_ON();
		bl_timer = timer;
		bl_timer_start = xTaskGetTickCount();
	}
}


void poll_back_light(void)
{
	
	{
		if((bl_timer != 0)&&(bl_timer != 0xff))
		{
			bl_timer_end = xTaskGetTickCount();
			if((bl_timer_end - bl_timer_start) >= (bl_timer * SWTIMER_COUNT_SECOND))
			{
				//BL_OFF();
				bl_timer = 0;
			}
		}
		if(bl_timer == 0)
			BL_OFF();
		if(bl_timer == 0xff)
			BL_ON();
	}
}


static void lcd_gpio_init(void)
{
	gpio_config_t io_conf = {0};

	io_conf.intr_type = GPIO_INTR_DISABLE;
	io_conf.mode = GPIO_MODE_OUTPUT;
	io_conf.pin_bit_mask = (1ULL << GPIO_LCD_BL) | (1ULL << GPIO_LCD_CS) |
		(1ULL << GPIO_LCD_RST) | (1ULL << GPIO_LCD_AO) |
		(1ULL << GPIO_LCD_CLK) | (1ULL << GPIO_LCD_DATA);
	io_conf.pull_down_en = 0;
	io_conf.pull_up_en = 0;
	gpio_config(&io_conf);

	LCD_CS_HI();
	LCD_AO_HI();
	LCD_RST_HI();
	LCD_CLK_HI();
	LCD_DATA_HI();
	BL_ON();
}

extern uint8 backlight_keep_seconds;
void ILI9341_Initial(void);
void LCD_Init(void)
{
//	uint8 i;
	if (xMutex == NULL)
		xMutex = xSemaphoreCreateRecursiveMutex();
	lcd_gpio_init();
	LCD_CS_LO();
	LCD_SCL_LO();
	LCD_SDA_LO();
	LCD_RES_LO();
	LCD_RS_LO();
	ILI9341_Initial();
	start_back_light(backlight_keep_seconds);
	ClearScreen(TSTAT8_BACK_COLOR);  //CLEAR DISPLAY
}

void menu_itoa(uint16 num, uint8 *p, uint8 dot)
{
	uint8 i = 0;
	if(num / 10000)
	{
		p[i++] = num / 10000 + '0';
		num %= 10000;

		p[i++] = num / 1000 + '0';
		num %= 1000;

		p[i++] = num / 100 + '0';
		num %= 100;

		p[i++] = num / 10 + '0';
		num %= 10;
	}
	else if(num / 1000)
	{
		p[i++] = num / 1000 + '0';
		num %= 1000;

		p[i++] = num / 100 + '0';
		num %= 100;

		p[i++] = num / 10 + '0';
		num %= 10;
	}
	else if(num / 100)
	{
		p[i++] = num / 100 + '0';
		num %= 100;

		p[i++] = num / 10 + '0';
		num %= 10;
	}
	else if(num / 10)
	{
		p[i++] = num / 10 + '0';
		num %= 10;
	}

	p[i++] = num + '0';
	p[i] = '\0';

	if(dot)
	{
		uint8 j;

		if(dot >= i)
		{
			i++;
			for(j = 0; j < i; j++)
				p[i - j] = p[i - j - 1];

			p[0] = '0';
		}

		for(j = 0; j < (dot + 1); j++)
			p[i - j + 1] = p[i - j];

		p[i - dot] = '.';
	}
}

void reset_main_net_status_counter(void)
{
	main_net_status_ctr = 10;
}

void poll_main_net_status(void)
{
	if(main_net_status_ctr)
		main_net_status_ctr--;
}

