void ClearScreen(unsigned int bColor)
{
		unsigned int i,j;
		LCD_SetPos(0,239,0,319);//320x240
		for (i=0;i<320;i++)
		{
			 for (j=0;j<240;j++)
					 Write_Data_U16(bColor);
		}
}






//==============================================================
//WRITE DATA WORD
void  Write_Data_U16(unsigned int y)
{
	unsigned char m,n;
	m=y>>8;
	n=y;
	Write_Data(m,n);

}
//=============================================================
//WRITE COMMAND
void Write_Cmd(unsigned char CMD)
{ unsigned char i;
    LCD_CS_LO();
		LCD_RS_LO();
    for(i=0;i<8;i++)
     {  LCD_SCL_LO();
        if(CMD&0x80) LCD_SDA_HI();
       	else LCD_SDA_LO();
       	LCD_SCL_HI();
        CMD=CMD<<1;
     }
   	LCD_CS_HI();
}

//===============================================================
//WRITE COMMAND PARAMETER 

void  Write_Cmd_Data (unsigned char CMDP)
{ unsigned char i;
    LCD_CS_LO();
   	LCD_RS_HI();
    for(i=0;i<8;i++)
     {  LCD_SCL_LO();
        if(CMDP&0x80) LCD_SDA_HI();
       	else LCD_SDA_LO();
       	LCD_SCL_HI();
        CMDP=CMDP<<1;
     }
   	LCD_CS_HI();
}


//===================================================================
//WRITE DATA CHAR

void Write_Data(unsigned char DH,unsigned char DL)
{unsigned char i;
    LCD_CS_LO();
   	LCD_RS_HI();
    for(i=0;i<8;i++)
     {  LCD_SCL_LO();
        if(DH&0x80) LCD_SDA_HI();
       	else LCD_SDA_LO();
       	LCD_SCL_HI();
        DH=DH<<1;
     }

    for(i=0;i<8;i++)
     {  LCD_SCL_LO();
        if(DL&0x80) LCD_SDA_HI();
       	else LCD_SDA_LO();
       	LCD_SCL_HI();
        DL=DL<<1;
     }

   	LCD_CS_HI();
}



