void LCD_Enter_Sleep(void) 
{ 
	Write_Cmd(0x28);     // Display off 
	Write_Cmd(0x10);     // Enter Sleep mode 
} 
 
void LCD_Exit_Sleep(void) 
{ 
	Write_Cmd(0x11);     // Sleep out 
	delay_ms(120); 
	Write_Cmd(0x29);     // Display on 
} 


//=============================================================
//LCD Initial
void ILI9341_Initial(void)
{	 
 	LCD_CS_HI();
	delay_ms(5);
	LCD_RES_LO();
	delay_ms(10);
	LCD_RES_HI();
	delay_ms(120);

	Write_Cmd(0x11);//exsit sleep mode
	delay_ms(120);

 	Write_Cmd(0xCF);   //power control B
	Write_Cmd_Data(0x00); 
	Write_Cmd_Data(0xc3); 
	Write_Cmd_Data(0X30); 
      
 	Write_Cmd(0xED); //power on sequence ontrol  
	Write_Cmd_Data(0x64); 
	Write_Cmd_Data(0x03); 
	Write_Cmd_Data(0X12); 
	Write_Cmd_Data(0X81); 
      
 	Write_Cmd(0xE8); //driver timing control A 
	Write_Cmd_Data(0x85); 
	Write_Cmd_Data(0x10); 
	Write_Cmd_Data(0x79); 
      
 	Write_Cmd(0xCB);//power control A   
	Write_Cmd_Data(0x39); 
	Write_Cmd_Data(0x2C); 
	Write_Cmd_Data(0x00); 
	Write_Cmd_Data(0x34); 
	Write_Cmd_Data(0x02); 
      
 	Write_Cmd(0xF7);//pump ratio control   
	Write_Cmd_Data(0x20); 
      
 	Write_Cmd(0xEA);//driver timing control B   
	Write_Cmd_Data(0x00); 
	Write_Cmd_Data(0x00); 
      
 	Write_Cmd(0xC0);    //Power control 
	Write_Cmd_Data(0x22);   //VRH[5:0] 
      
 	Write_Cmd(0xC1);    //Power control 
	Write_Cmd_Data(0x11);   //SAP[2:0];BT[3:0] 
      
 	Write_Cmd(0xC5);    //VCM control 
	Write_Cmd_Data(0x3d); 
    //LCD_DataWrite_ILI9341(0x30); 
	Write_Cmd_Data(0x20); 
      
 	Write_Cmd(0xC7);    //VCM control2 
    //LCD_DataWrite_ILI9341(0xBD); 
	Write_Cmd_Data(0xAA); //0xB0 
    
 	Write_Cmd(0x36);    // Memory Access Control 
	Write_Cmd_Data(0xc8); //Row address order//XY exchange and X mirror
      
 	Write_Cmd(0x3A);   //color mode
	Write_Cmd_Data(0x55); 
    
 	Write_Cmd(0xB1); //frame rate control  
	Write_Cmd_Data(0x00);   
	Write_Cmd_Data(0x13); 
      
 	Write_Cmd(0xB6);    // Display Function Control 
	Write_Cmd_Data(0x0A); 
	Write_Cmd_Data(0xA2); 
    
 	Write_Cmd(0xF6); //interface control    
	Write_Cmd_Data(0x01); 
//	Write_Cmd_Data(0x00);//data will be ignore if over the range
	Write_Cmd_Data(0x30); 
      
 	Write_Cmd(0xF2);    // 3Gamma Function Disable 
	Write_Cmd_Data(0x00); 
      
 	Write_Cmd(0x26);    //Gamma curve selected 
	Write_Cmd_Data(0x01); 
      
 	Write_Cmd(0xE0);    //Set Gamma 
	Write_Cmd_Data(0x0F); 
	Write_Cmd_Data(0x3F); 
	Write_Cmd_Data(0x2F); 
	Write_Cmd_Data(0x0C); 
	Write_Cmd_Data(0x10); 
	Write_Cmd_Data(0x0A); 
	Write_Cmd_Data(0x53); 
	Write_Cmd_Data(0XD5); 
	Write_Cmd_Data(0x40); 
	Write_Cmd_Data(0x0A); 
	Write_Cmd_Data(0x13); 
	Write_Cmd_Data(0x03); 
	Write_Cmd_Data(0x08); 
	Write_Cmd_Data(0x03); 
	Write_Cmd_Data(0x00); 
      
 	Write_Cmd(0XE1);    //Set Gamma 
	Write_Cmd_Data(0x00); 
	Write_Cmd_Data(0x00); 
	Write_Cmd_Data(0x10); 
	Write_Cmd_Data(0x03); 
	Write_Cmd_Data(0x0F); 
	Write_Cmd_Data(0x05); 
	Write_Cmd_Data(0x2C); 
	Write_Cmd_Data(0xA2); 
	Write_Cmd_Data(0x3F); 
	Write_Cmd_Data(0x05); 
	Write_Cmd_Data(0x0E); 
	Write_Cmd_Data(0x0C); 
	Write_Cmd_Data(0x37); 
	Write_Cmd_Data(0x3C); 
	Write_Cmd_Data(0x0F); 
	
//	Write_Cmd(0x33);   //color mode
//	Write_Cmd_Data(0x55);
//	Write_Cmd_Data(0x55);
//	Write_Cmd_Data(0x55);
//	Write_Cmd_Data(0x55);
//	Write_Cmd_Data(0x55);
//	Write_Cmd_Data(0x55);
      
 	Write_Cmd(0x11);    //Exit Sleep 
	delay_ms(120);
 	Write_Cmd(0x29);    //Display on 
	delay_ms(50);
}

	   

//===============================================================
//Define the coordinate
static void LCD_SetPos(unsigned char x0,unsigned char x1,unsigned int y0,unsigned int y1)
{unsigned char YSH,YSL,YEH,YEL;

	//__disable_irq();
	YSH=y0>>8;
	YSL=y0;

	YEH=y1>>8;
	YEL=y1;

 	Write_Cmd(0x2A);
	Write_Cmd_Data (0x00);
	Write_Cmd_Data (x0);
	Write_Cmd_Data (0x00);
	Write_Cmd_Data (x1);
	Write_Cmd(0x2B);
	Write_Cmd_Data (YSH);
	Write_Cmd_Data (YSL);
	Write_Cmd_Data (YEH);
	Write_Cmd_Data (YEL);
	Write_Cmd(0x2C);//LCD_WriteCMD(GRAMWR);
	//__enable_irq();
}


//8*12??

void disp_ch(uint8 form, uint16 x, uint16 y,uint8 value,uint16 dcolor,uint16 bgcolor)	
{  
	uint16 i,j;
	uint8 const *temp ;//= chlibsmall;  
  uint16 cp = 0;
	uint16 pp = 0;
	uint16 cnum;
	
	if(form == FORM32X64)
		{
		temp = chlib;
		cp = 72; pp = 40;

		if(value == '-')
			temp += 10 * pp*cp/8;	
		else if(value == ' ')
      temp += 11 * pp*cp/8;
		else if(value == '.')
			temp += 12 *pp*cp/8;
		else	
			temp += (value - 48) * pp*cp/8;				
			
//		cp = 48; pp = 96;

//		if(value == '-')
//			temp += 10 * 576;	
//		else if(value == ' ')
//      temp += 11 * 576;			
//		else	
//			temp += (value - 48) * 576;	
		}
	else if(form == FORM15X30)
		{
		temp = chlibsmall;
		cp = 32; pp = 24;
		temp += (value - ' ') * pp*cp/8;					
			
//		temp = chlibsmall;
//		cp = 24; pp = 36;
//		temp += (value - 32) * 108;		
		}
		
		else
		{
			temp = chlibmiddle;
			cp = 32; pp = 16;
			temp += (value - ' ') * pp*cp/8;
		}
		
		LCD_SetPos(x,x+cp-1,y,y+pp-1);

	cnum = pp*cp/8 ;
	
  	
	for(j=0;j<cnum;j++)
		{
		for(i=0;i<8;i++)
			{ 		     
		 	if(((*temp >> i) & 0x01)!=0)
				{
				Write_Data(dcolor>>8,dcolor);
				} 
			else
				{
				Write_Data(bgcolor>>8,bgcolor);
				} 	
			}
		temp++;
		}
}

void disp_str(uint8 form, uint16 x,uint16 y,uint8 *str,uint16 dcolor,uint16 bgcolor)	  
{  
	unsigned int x1,y1;
	x1=x;
	y1=y;
	//vTaskSuspendAll();
	while(*str!='\0')
	{	
		
		disp_ch(form,x1,y1,*str,dcolor,bgcolor);
//		if(form == FORM48X120) //big form
//			x1+=47;
//		else			
//			x1+=15;	
			
		if(form == FORM32X64) //big form
			//y1-=31;
			y1-= 40;
		else if( form == FORM15X30)
			y1-=23;	
		else
			y1-=15;
		str++;
	}	
	//xTaskResumeAll();
}



void disp_icon(uint16 cp, uint16 pp, uint16 const *icon_name, uint16 x,uint16 y,uint16 dcolor, uint16 bgcolor)	
{  
	uint16 j;
	//uint6 const *temp = icon_name;  
	uint16 cnum;

	cnum = pp*cp;
	//vTaskSuspendAll();
  LCD_SetPos(x,x+cp-1,y,y+pp-1);	
	for(j=0;j<cnum;j++)
		{
			Write_Data(icon_name[j]>>8,icon_name[j]);	
		}
		//xTaskResumeAll();
}

void disp_null_icon(uint16 cp, uint16 pp, uint16 x,uint16 y,uint16 dcolor, uint16 bgcolor)	
{  
	uint16 j;
	//uint6 const *temp = icon_name;  
	uint16 cnum;

	cnum = pp*cp;
	
  LCD_SetPos(x,x+cp-1,y,y+pp-1);	
	for(j=0;j<cnum;j++)
		{
			Write_Data(bgcolor>>8,bgcolor);	
		}
}


