uint8_t lcd_rotate_max=4;

void Refresh_scroll(void)
{
	uint8 i,j;
	uint8 length;
	uint8 text[50];
	if(lcd_rotate_max > 9)
		lcd_rotate_max = 9;
	if(lcd_rotate_max > 0)
	{
		for(i=0;i<lcd_rotate_max;i++)
		{
			switch(i)//disp_item_queue(i))
			{
				case 0://heat/cool stage
					memcpy((uint8_t *)scroll_ram[i] , color_time, strlen((char *)color_time));
				break;	

				case 1://heat/cool stage
					memcpy((uint8_t *)scroll_ram[i] , date, strlen((char *)date));
				break;	
#if 0				
				case 2: // network					
					length =  strlen((char *)network_status_text);
					memcpy((uint8_t *)scroll_ram[i],network_status_text,length);
					if(main_net_status_ctr)
					{
						//length = strlen((char *)net_status_ok_text);
						memcpy((uint8_t *)&scroll_ram[i][length], net_status_ok_text, strlen((char *)net_status_ok_text));
					}
					else
					{
						memcpy((uint8_t *)&scroll_ram[i][length], net_status_dead_text, strlen((char *)net_status_dead_text));
					}
				break;
				
				case 3: //time					
					length = strlen((char *)alarm_text);
					memcpy((uint8_t *)scroll_ram[i],alarm_text, length);
					if((alarm_state & (~ALARM_MANUAL)) == STOP_ALARM)
					{
						memcpy((uint8_t *)&scroll_ram[i][length],  alarm_status_text[STOP_ALARM], 4);//strlen((char *)alarm_status_text[STOP_ALARM]));
					}
					else
					{
						//U8_T i, id_temp;
							{
								//if(isColorScreen == false)
								{
									if(internal_co2_exist == TRUE)
									{ 
										sprintf((char *)text, "%s:%s,", internal_text, alarm_status_text[int_co2_str.alarm_state]);
										//length = strlen((char *)text);
										memcpy((uint8_t *)&scroll_ram[i][length],  text, strlen((char *)text));
									}
								}
							}
					}
				break;
				case 4:  // only for multi-I2C sensor
					//if(PRODUCT_ID == STM32_PM25) 		break;
					//if(PRODUCT_ID == STM32_PRESSURE_NET)		break;
					//if((PRODUCT_ID == STM32_CO2_NET) && (Mul_i2c_data.screenArea[0] == SCREEN_AREA_NONE))
						break;
#endif					
				default:
				break;
			}
		}
	}
}

uint8_t Get_channel_by_lcd_index(uint8_t lcd_index);
void display_scroll(void)
{
	uint8 cnt;
	uint8 i;
	
	/*if(i2c_sht_num + i2c_co2_num > 1)
	{
		lcd_rotate_max = 1;
		//lcd_i2c_sensor_index
		i = Get_channel_by_lcd_index(lcd_i2c_sensor_index);
		if(i == 0)
		memcpy((uint8_t *)scroll_ram[0] , "Channel 1 ", 11);
		else if(i == 1)
		memcpy((uint8_t *)scroll_ram[0] , "Channel 2 ", 11);
		else if(i == 2)
		memcpy((uint8_t *)scroll_ram[0] , "Channel 3 ", 11);
		else
			memcpy((uint8_t *)scroll_ram[0] , " 				", 11);
	}
	else*/
		Refresh_scroll();
	//vTaskSuspendAll();
	if(lcd_rotate_max == 1)
	{
		for(i=0;i<13;i++)
			scroll_buf[i] = scroll_ram[lcd_rotate_max-1][i];
		scroll_buf[13] = '\0'; 
		disp_str(FORM15X30, 205,280,scroll_buf,TSTAT8_CH_COLOR,TSTAT8_MENU_COLOR2); 
	}
	
	else if(lcd_rotate_max > 1)
	{
		if(scroll >= &scroll_ram[lcd_rotate_max-1][1])
		{
			for(i=0;i<(&scroll_ram[lcd_rotate_max-1][SCOROLL_BUFF_LEN-1] - scroll + 1);i++)
				scroll_buf[i] = *(scroll+i);
			for(i=0;i<(scroll + (SCOROLL_BUFF_LEN-1) - &scroll_ram[lcd_rotate_max-1][SCOROLL_BUFF_LEN-1]);i++)
				scroll_buf[&scroll_ram[lcd_rotate_max-1][SCOROLL_BUFF_LEN-1] - scroll + 1 + i] = scroll_ram[0][i];
		}
		else
		{
			for(i=0;i<SCOROLL_BUFF_LEN-2;i++)
				scroll_buf[i] = *(scroll+i);
		}
		if(scroll == &scroll_ram[lcd_rotate_max-1][SCOROLL_BUFF_LEN-1])
			scroll = &scroll_ram[0][0];	
		else	
			scroll++;
		
		scroll_buf[SCOROLL_BUFF_LEN-2] = '\0'; 
		disp_str(FORM15X30, 205,280,scroll_buf,TSTAT8_CH_COLOR,TSTAT8_MENU_COLOR2); 
	}
	//xTaskResumeAll();
}

