static uint8 idle_showing_var;
static uint8 idle_var_unit;
void Display_TEMP(uint8_t line,int16 value)
{
	int16 value_buf;
	uint16_t pos = 0;
	if(line == 0) 
	{
		pos = THERM_METER_POS;
		if(flag_nosensor1 == 0)	
			disp_icon(14, 14, degree_o, 30 + pos ,UNIT_POS+20-40,TSTAT8_CH_COLOR, TSTAT8_BACK_COLOR);
	}
	if(line == 1)
	{
		pos = HUM_POS;
		if(flag_nosensor1 == 0)	
			disp_icon(14, 14, degree_o, 30 + pos ,UNIT_POS+20-40,TSTAT8_CH_COLOR, TSTAT8_BACK_COLOR);
	}
	if(line == 2)
	{
		pos = 160;
		if(flag_nosensor1 == 0)	
			disp_icon(14, 14, degree_o, 30 + pos ,UNIT_POS+20-40,TSTAT8_CH_COLOR, TSTAT8_BACK_COLOR);
	}
	

	if(value >=0)
	{
		value_buf = value;
		disp_null_icon(5, 15, pos + 32,245,TSTAT8_BACK_COLOR, TSTAT8_BACK_COLOR);
		if(value >= 1000)
		{
			//value_buf /= 10;
			if(value_buf >= 1000)
				disp_ch(0,pos,FIRST_CH_POS,0x30+value_buf/1000,TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);
			else 
				disp_ch(0,pos,FIRST_CH_POS,' ',TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);
			
			disp_ch(0,pos,SECOND_CH_POS,0x30+(value_buf%1000)/100,TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);
			disp_ch(0,pos,THIRD_CH_POS+16,0x30+(value_buf%100)/10,TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);	
			disp_ch(0,pos,THIRD_CH_POS+16-40-16,0x30+value_buf%10,TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);	
		}
		if(value < 1000)
		{
			disp_ch(0,pos,FIRST_CH_POS,' ',TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);
			if(value >= 100)
				disp_ch(0,pos,SECOND_CH_POS,0x30+value_buf/100,TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);
			else 
				disp_ch(0,pos,SECOND_CH_POS,' ',TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);
			disp_ch(0,pos,THIRD_CH_POS+16,0x30+(value_buf%100)/10,TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);
			disp_ch(0,pos,THIRD_CH_POS+16-40-16,0x30+value_buf%10,TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);
		}
		else if(value < 100)
		{
			disp_ch(0,pos,FIRST_CH_POS,' ',TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);
			disp_ch(0,pos,SECOND_CH_POS,0x30+value_buf/1000,TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);
			disp_ch(0,pos,THIRD_CH_POS+16,0x30+(value_buf%1000)/100,TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);
			disp_ch(0,pos,THIRD_CH_POS+16-40-16,0x30+(value_buf%100)/10,TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);		
		}
	}
	else//nagtive value
	{
		value_buf = -value;				
		disp_null_icon(3, 10, pos + 32, 245,TSTAT8_CH_COLOR, TSTAT8_CH_COLOR);//ÏÔÊ¾¸ººÅ
		
		if(value_buf >= 100)
		{
			disp_ch(0,pos,FIRST_CH_POS,' ',TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);	
			disp_ch(0,pos,SECOND_CH_POS,0x30+value_buf/100,TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);
			disp_ch(0,pos,THIRD_CH_POS+16,0x30+(value_buf%100)/10,TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);	
			disp_ch(0,pos,THIRD_CH_POS+16-40-16,0x30+value_buf%10,TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);
		}
		else if(value_buf < 100)
		{

		disp_ch(0,pos,FIRST_CH_POS,' ',TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);	
		disp_ch(0,pos,SECOND_CH_POS,' ',TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);	
		disp_ch(0,pos,THIRD_CH_POS+16,0x30+(value_buf%100)/10,TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);	
		disp_ch(0,pos,THIRD_CH_POS+16-40-16,0x30+value_buf%10,TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);			
		}
	}
	
	if(idle_showing_var)
	{
		if(idle_var_unit == TOP_AREA_DISP_UNIT_F)
			disp_str(FORM15X30, 33+pos,UNIT_POS-1-40,(uint8 *)"F ",TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);
		else
			disp_str(FORM15X30, 33+pos,UNIT_POS-40,(uint8 *)"C ",TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);
	}
	else if(HUM_data.deg_c_or_f == DEGREE_C)
		disp_str(FORM15X30, 33+pos,UNIT_POS-40,(uint8 *)"C ",TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);
	else
		disp_str(FORM15X30, 33+pos,UNIT_POS-1-40,(uint8 *)"F ",TSTAT8_CH_COLOR,TSTAT8_BACK_COLOR);
	
}

